/* Browser-only product prototype; every state is ephemeral and simulated. */
(() => {
  'use strict';
  const D=window.DEMO, $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const initial=()=>({demo:false,role:'buyer',tab:'all',search:'',warehouse:'all',store:'all',sort:'risk',late:false,scenarioRevision:0,jobSequence:0,detailTab:'overview',job:null,suggestion:null,approval:null,audit:[],evidenceDenied:false});
  let state=initial(),jobTimer,toastTimer,returnFocus;
  const badge=(t,c='')=>`<span class="badge ${c}">${t}</span>`;
  const btn=(label,action,cls='',attrs='')=>`<button class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
  const status=r=>badge(...D.states[r.status]);
  const notice=(title,body,type='info')=>`<div class="notice ${type}" role="${type==='danger'?'alert':'status'}"><span class="notice-symbol">${type==='danger'?'⊗':type==='warning'?'△':'ⓘ'}</span><div><strong>${title}</strong><p>${body}</p></div></div>`;
  const rowById=id=>D.rows.find(x=>x.id===id)||D.rows[0];
  function route(){const parts=location.hash.slice(1).split('/');return {page:parts[0]||'workbench',id:parts[1]||'RP-001'};}
  function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
  function go(target){if(location.hash===`#${target}`)render();else location.hash=target;}
  function modal(title,body,foot=''){returnFocus=document.activeElement;$('#modal-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close" aria-label="关闭对话框">×</button></div><div class="dialog-body">${body}</div>${foot?`<div class="dialog-foot">${foot}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal();}
  function close(){if($('#modal').open)$('#modal').close();returnFocus?.focus?.();}
  function log(text){state.audit.unshift({text,time:'刚刚 · 演示会话'});}
  function head(eyebrow,title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="button-row">${actions}</div></div>`;}
  // Report references are fixtures; scenario revisions never republish or rewrite them.
  const SOURCE_REPORT='task-demo-1111 / plan-v1 / report-v1';
  const currentSuggestion=()=>!!state.suggestion&&state.suggestion.status!=='SUPERSEDED'&&state.suggestion.sourceReport===SOURCE_REPORT&&!state.late&&state.suggestion.scenarioRevision===state.scenarioRevision;
  const currentApproval=()=>currentSuggestion()&&state.approval?.version===state.suggestion.version&&state.approval?.scenarioRevision===state.scenarioRevision&&state.approval?.sourceReport===state.suggestion.sourceReport;
  function contextNotice(){const s=state.suggestion;return s?.status==='SUPERSEDED'?notice('情景已变更：旧建议及审批已失效',`建议 v${s.version} / ${esc(s.sourceReport)} 保留为历史记录；旧确认、待审批和批准均不可复用。${state.late?'延期样例需重新分析，本原型不生成新方案。':'已切回原计划，仍须重新选择候选、生成新版本并确认提交。'}`,'danger'):state.late?notice('CB-1001 正在预览延期情景','历史 report-v1 保持原计划；延期逐日样例未发布为新报告，不适用于其他商品。','warning'):'';}
  function changeScenario(late){if(state.late===late)return;state.late=late;state.scenarioRevision++;if(state.suggestion&&state.suggestion.status!=='SUPERSEDED'){state.suggestion.status='SUPERSEDED';log(`供给日期情景变更，建议 v${state.suggestion.version} SUPERSEDED；原确认及审批 ${state.approval?.status||'未创建'} 不再适用，切回也不恢复。`);}if($('#modal').open)close();render();toast('情景已变更；旧确认及审批不可复用，历史报告未改写。');}
  function workbench(){
    const job=state.job;
    return head('PURCHASING / OVERVIEW','采购工作台','先处理阻断，再复核补货方案。',btn('＋ 新建补货分析','new-analysis','primary'))+
    `<section class="hero-overview"><div><div class="hero-status"><span class="status-dot"></span>历史固定报告 · report-v1 / 模拟样例</div><h2>4 项候选待复核，4 项采购结论已阻断</h2><p class="muted">Amazon 美国站 / Shopify 独立站 · 美西仓 / 美东仓 · 8 个 SKU</p></div><a class="button" href="#suggestions">查看历史结果 <span>→</span></a></section>`+
    `<div class="metrics"><button class="metric" data-action="filter-ready"><span class="metric-label">候选待复核</span><span class="metric-arrow">↗</span><div class="metric-value num">4<small>项</small></div><span class="metric-foot">按缓冲缺口优先复核</span></button><button class="metric" data-action="filter-blocked"><span class="metric-label">数据 / 质量阻断</span><span class="metric-arrow">↗</span><div class="metric-value num danger-text">4<small>项</small></div><span class="metric-foot">补证后需重新分析</span></button><button class="metric" data-action="open-approvals"><span class="metric-label">待独立审批 · 演示</span><span class="metric-arrow">↗</span><div class="metric-value num">${currentApproval()&&state.approval.status==='PENDING'?1:0}<small>项</small></div><span class="metric-foot">审批能力尚未启用</span></button><div class="metric"><span class="metric-label">当前数据快照</span><div class="metric-value num" style="font-size:23px;padding-block:5px">08:00<small>UTC+8</small></div><span class="metric-foot mono">snap-demo-1111 / v1</span></div></div>`+
    contextNotice()+(job?`<section class="panel" style="margin-bottom:20px"><div class="panel-head"><h2>本次模拟分析（独立于历史报告） <small>${esc(job.id)}</small></h2>${badge(job.status,job.status==='已发布'?'success':'info')}</div><div class="panel-body"><div class="button-row"><span class="small">${esc(job.message)}</span>${job.status==='运行中'?btn('取消分析','cancel-job'):job.report?`<span class="small mono">本次产物：${esc(job.report)}</span><a class="button small" href="#detail/RP-001">对照历史固定报告</a>`:''}</div></div></section>`:'')+
    `<div class="columns"><div><section class="panel"><div class="panel-head"><h2>优先处理 <small>按业务影响排序</small></h2><a href="#suggestions" class="small">全部建议 →</a></div>
    ${[
      ['01','BT-2003 · 保温随行杯','质量信号待调查，暂停转采购。','quality','RP-002','查看质量依据'],
      ['02','LT-3012 · 便携阅读灯','库存覆盖过期，当前缺货日期不可用。','stale','RP-003','查看数据缺口'],
      ['03','CB-1001 · 旅行收纳包','7 天窗口与 2 天缓冲，候选补货 20 件。','ready','RP-001','复核补货方案']
    ].map(x=>`<div class="priority-row"><span class="priority-num">${x[0]}</span><div class="priority-title">${x[1]}<p class="muted">${x[2]}</p>${status({status:x[3]})}</div><a class="button small" href="#detail/${x[4]}">${x[5]} →</a></div>`).join('')}</section>
    <section class="panel"><div class="panel-head"><h2>历史固定报告</h2>${badge('只读报告')}</div><div class="table-scroll"><table><thead><tr><th>报告 / 范围</th><th>完整性</th><th>发布时点</th><th></th></tr></thead><tbody><tr><td><b>补货分析 · 11 月 11 日</b><small class="product-sub">8 个 SKU · 固定模拟输入</small></td><td>${badge('部分结果 PARTIAL','warning')}</td><td class="num">08:05</td><td><a href="#suggestions">查看 →</a></td></tr><tr><td><b>CB-1001 · 规则基线</b><small class="product-sub">7 天需求 / 2 天缓冲</small></td><td>${badge('规则报告 RULES_ONLY','info')}</td><td class="num">08:03</td><td><a href="#detail/RP-001">查看 →</a></td></tr></tbody></table></div></section></div>
    <aside><section class="panel"><div class="panel-head"><h2>数据准备情况</h2>${badge('模拟')}</div><div class="panel-body"><div class="source-item"><div>OMS 需求<small>覆盖至 11-11 08:00</small></div>${badge('可用','success')}</div><div class="source-item"><div>WMS 库存<small>LT-3012 覆盖过期</small></div>${badge('1 项缺口','warning')}</div><div class="source-item"><div>ERP 未收供给<small>LT-3021 供给重复</small></div>${badge('1 项缺口','warning')}</div><div class="source-item"><div>质量结果引用<small>1 项异常 / 1 项缺失</small></div>${badge('2 项待核','danger')}</div><p class="micro-note">各数据域独立检查覆盖与时效。缺失字段保留未知，不按 0 处理。</p></div></section><section class="panel"><div class="panel-head"><h2>工作边界</h2></div><div class="panel-body"><p class="small">分析发布后由采购复核。选方案、确认、提交审批与外部执行分别触发。</p><p class="micro-note">当前 S01 到只读报告结束；所有采购流转均为会话内演示。</p>${btn('查看原型覆盖范围','about','link')}</div></section></aside></div>`;
  }
  function filtered(){let rows=D.rows.filter(r=>(state.tab==='all'||(state.tab==='ready'?r.status==='ready':r.status!=='ready'))&&(state.warehouse==='all'||r.warehouse===state.warehouse)&&(state.store==='all'||r.store===state.store)&&`${r.sku} ${r.name}`.toLowerCase().includes(state.search.toLowerCase()));if(state.sort==='sku')rows.sort((a,b)=>a.sku.localeCompare(b.sku));else if(state.sort==='date')rows.sort((a,b)=>(a.shortage||'99').localeCompare(b.shortage||'99'));else rows.sort((a,b)=>(a.status==='ready')-(b.status==='ready'));return rows;}
  function resultRows(){return filtered().map(r=>`<tr><td><div class="sku-cell"><span class="sku-mark">${r.sku.slice(0,2)}</span><div><a class="product-name" href="#detail/${r.id}">${r.name}</a><span class="product-sub mono">${r.sku}</span></div></div></td><td>${r.store}<span class="product-sub">${r.warehouse}</span></td><td class="right num">${r.available??'—'}<span class="product-sub">${r.available===null?'不可用':'件'}</span></td><td class="num">${r.shortage?`2026-${r.shortage}`:'—'}<span class="product-sub">${r.shortage?'原计划基线（含原供给）':'结论已阻断'}</span></td><td class="right num">${r.qty??'—'}<span class="product-sub">${r.qty?'件 / 候选':'不生成候选'}</span></td><td>${status(r)}<span class="product-sub">${r.risk}</span></td><td><a href="#detail/${r.id}">查看详情 →</a></td></tr>`).join('');}
  function tableBody(){const rows=filtered();return rows.length?`<div class="table-scroll"><table class="table-list"><caption class="sr-only">补货候选与阻断项，每行可打开详情</caption><thead><tr><th>商品 / SKU</th><th>店铺 / 仓库</th><th class="right">可售库存</th><th>首次短缺日</th><th class="right">候选数量</th><th>复核状态 / 原因</th><th>操作</th></tr></thead><tbody>${resultRows()}</tbody></table></div><div class="table-foot"><span>共 ${rows.length} 项 · 单位：件</span><span>第 1 / 1 页</span></div>`:`<div class="empty"><div style="font-size:24px">⌕</div><h2>没有匹配的建议</h2><p>试试其他 SKU、仓库或复核状态。</p>${btn('清空筛选','clear-filters')}</div>`;}
  function suggestions(){return head('PURCHASING / RECOMMENDATIONS','补货建议','历史 report-v1 / 原计划；分析候选与业务建议分开管理。',btn('导出演示结果','export')+btn('＋ 新建补货分析','new-analysis','primary'))+
    contextNotice()+notice('4 项采购结论被阻断','请先复核数据和质量依据；阻断项不会提供可执行采购候选。','warning')+
    `<section class="panel"><div class="tabs" aria-label="结果筛选">${[['all','全部',8],['ready','候选待复核',4],['blocked','数据 / 质量阻断',4]].map(x=>`<button class="tab ${state.tab===x[0]?'active':''}" aria-pressed="${state.tab===x[0]}" data-action="tab" data-value="${x[0]}">${x[1]}<span>${x[2]}</span></button>`).join('')}</div><div class="toolbar"><div class="filters"><label class="search"><span aria-hidden="true">⌕</span><input id="search" aria-label="搜索商品或 SKU" placeholder="搜索商品名称、SKU" value="${esc(state.search)}"></label><select id="store" aria-label="按店铺筛选"><option value="all">全部店铺</option>${['Amazon 美国站','Shopify 独立站'].map(s=>`<option ${state.store===s?'selected':''}>${s}</option>`).join('')}</select><select id="warehouse" aria-label="按仓库筛选"><option value="all">全部仓库</option>${['美西仓','美东仓'].map(s=>`<option ${state.warehouse===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="filters"><select id="sort" aria-label="排序"><option value="risk" ${state.sort==='risk'?'selected':''}>阻断优先</option><option value="date" ${state.sort==='date'?'selected':''}>首次短缺日 ↑</option><option value="sku" ${state.sort==='sku'?'selected':''}>SKU ↑</option></select>${btn('重置','clear-filters','link')}</div></div><div id="result-table">${tableBody()}</div></section><p class="micro-note">表内数量、状态及短缺日均为历史原计划，不随详情情景切换而重算。未补货基线包含原未收供给，不包含候选采购。详情页区分原供给与候选采购的预计可售日；到港时间不作为可售时间。</p>`;}
  function chart(){const base=D.daily[state.late?'lateBase':'base'],planned=D.daily[state.late?'late':'normal'];const points=a=>a.map((v,i)=>`${48+i*68},${180-v*2.1}`).join(' ');return `<svg class="chart" viewBox="0 0 630 255" role="img" aria-label="${state.late?'延期情景：D6 首次短缺':'供需推演：原计划 D8 首次短缺，候选方案无短缺'}"><text x="10" y="16">件</text>${[60,40,20,0,-20].map(v=>`<line x1="42" x2="605" y1="${180-v*2.1}" y2="${180-v*2.1}" stroke="${v===0?'#aebbc6':'#e9eef1'}" ${v===0?'stroke-dasharray="3 4"':''}/><text x="16" y="${184-v*2.1}">${v}</text>`).join('')}<polyline points="${points(base)}" fill="none" stroke="#9aabba" stroke-width="2" stroke-dasharray="5 5"/><polyline points="${points(planned)}" fill="none" stroke="${state.late?'#ad3733':'#126b65'}" stroke-width="2.5"/>${planned.map((v,i)=>`<circle cx="${48+i*68}" cy="${180-v*2.1}" r="3" fill="${v<0?'#ad3733':'#126b65'}"/><text x="${48+i*68}" y="242" text-anchor="middle">D${i+1}</text>`).join('')}<text x="${state.late?388:388}" y="27" text-anchor="middle">${state.late?'原供给、候选均 D8 可售 → D6 短缺':'原供给 D4 可售 / 候选 D6 可售'}</text></svg><div class="legend"><span><i class="dashed"></i>基线（含原供给，不含候选）</span><span><i style="${state.late?'background:#ad3733':''}"></i>加入候选采购后的情景</span></div>`;}
  function detail(){const r=rowById(route().id),base=r.id==='RP-001',blocked=r.status!=='ready',block=D.blockers[r.status];
    return `<a class="back" href="#suggestions">← 返回补货建议</a><div class="detail-top"><div class="detail-title"><span class="sku-mark">${r.sku.slice(0,2)}</span><div><div class="eyebrow">${r.id} / REPLENISHMENT REVIEW</div><h1>${r.name}</h1><p class="subtitle"><span class="mono">${r.sku}</span>　${r.store} / ${r.warehouse}</p></div></div><div class="button-row">${base&&state.late?badge('需重新规划','danger'):status(r)}${badge('历史 report-v1 / 原计划')}</div></div>`+
    (base?contextNotice():'')+(blocked?notice(block[0],block[1],'danger'):base&&state.late?notice('日期变化：旧候选不能继续使用','原供给与候选采购均延至 D8 可售，D6 首次短缺。请重做方案并重新确认；旧批准不覆盖新输入。','danger'):notice('候选可供复核，不代表采购批准','本方案满足演示 MOQ 与订购倍数；预计可售日为假设，供应商尚未承诺。'))+
    `<div class="detail-grid"><div><section class="panel"><div class="tabs" aria-label="详情内容">${[['overview','方案与依据'],['evidence','证据与版本']].map(x=>`<button class="tab ${state.detailTab===x[0]?'active':''}" data-action="detail-tab" data-value="${x[0]}" aria-pressed="${state.detailTab===x[0]}">${x[1]}</button>`).join('')}</div><div class="panel-body">`+
    (state.detailTab==='evidence'?evidencePanel(r):`<div class="summary-grid"><div class="summary-item"><small>当前可售</small><strong class="num">${r.available??'—'} <span>件</span></strong><p>${r.available===null?'覆盖过期，不发布数值':'固定输入事实'}</p></div><div class="summary-item"><small>目标库存</small><strong class="num">${base?'90':'—'} <span>件</span></strong><p>${base?'7 天需求 + 2 天缓冲':'未提供完整指标样例'}</p></div><div class="summary-item"><small>目标缺口</small><strong class="num">${base?'15':'—'} <span>件</span></strong><p>${base?(state.late?'历史指标含原供给20件；延期未重算':'历史指标含 D4 原供给20件'):'不由浏览器推算'}</p></div><div class="summary-item"><small>候选补货</small><strong class="num ${blocked?'':'success-text'}">${blocked?'—':r.qty} <span>件</span></strong><p>${blocked?'采购结论已阻断':base?'MOQ 10 / 倍数 10':'独立展示样例'}</p></div></div>`+
    (base?`<div class="section-head"><h2>逐日供需推演</h2><label class="small muted">样例情景　<select id="scenario" class="button small"><option value="normal" ${state.late?'':'selected'}>原计划 · 原供给D4 / 候选D6</option><option value="late" ${state.late?'selected':''}>延期 · 均延至 D8</option></select></label></div>${chart()}<p class="chart-caption">D1 = 2026-11-11；D4=11-14，D6=11-16，D8=11-18。余额为当日供给入账、扣新增需求后的日末净额；负值表示累计未满足需求，不是实物负库存。基线含原供给20件，候选行另加采购20件。仅绘制已存样例；90/15仍是历史指标，延期未重算。</p><details style="margin-top:14px"><summary class="small">查看每日余额（件）</summary><div class="table-scroll"><table><thead><tr><th>情景</th>${D.daily.normal.map((_,i)=>`<th>D${i+1}</th>`).join('')}</tr></thead><tbody><tr><td>基线（仅原供给20件）</td>${D.daily[state.late?'lateBase':'base'].map(v=>`<td class="num">${v}</td>`).join('')}</tr><tr><td>原供给20件 + 候选采购20件</td>${D.daily[state.late?'late':'normal'].map(v=>`<td class="num ${v<0?'danger-text':''}">${v}</td>`).join('')}</tr></tbody></table></div></details>`:blocked?`<div class="empty" style="padding:25px 0"><h2>暂不生成补货候选</h2><p>${block[2]}</p>${btn('查看来源证据','evidence','',`data-id="${r.id}"`)}</div>`:notice('本商品仅演示列表与详情结构','完整逐日推演、库存分桶与候选比较请查看 CB-1001。此处不编造未提供的明细。'))+
    (base?`<div style="border-top:1px solid var(--line);margin-top:22px;padding-top:18px"><h2>输入与业务约束</h2><div class="facts"><div class="fact"><span>现货 / 预留</span><strong>100 / 30 件</strong></div><div class="fact"><span>冻结 / 不可售</span><strong>10 / 5 件</strong></div><div class="fact"><span>日新增需求</span><strong>10 件 / 天</strong></div><div class="fact"><span>需求 / 缓冲窗口</span><strong>7 天 / 2 天</strong></div><div class="fact"><span>原未收供给</span><strong>20 件 · ${state.late?'D8':'D4'} 可售</strong></div><div class="fact"><span>MOQ / 订购倍数</span><strong>10 / 10 件</strong></div><div class="fact"><span>质量依赖</span><strong>演示兼容结果 / 可用</strong></div><div class="fact"><span>交期依据</span><strong>假设 / 待供应商确认</strong></div></div></div>`:''))+
    `</div></section>${base?`<section class="panel"><div class="panel-head"><h2>备选路径</h2><small>方案比较 / 不作供应承诺</small></div><div class="table-scroll"><table><thead><tr><th>路径</th><th>数量 / 可售日</th><th>评价与下一步</th></tr></thead><tbody><tr><td>常规补货</td><td>20 件 / ${state.late?'D8（延期样例）':'D6（原计划）'}</td><td>${state.late?'旧方案已失效，需重规划':'覆盖目标；需确认交期与证据'}</td></tr><tr><td>加急协调</td><td>20 件 / 假设 D4</td><td>待询价与可行性确认；未计算费用</td></tr><tr><td>先调查</td><td>不形成采购数量</td><td>质量信号异常或缺失时优先</td></tr></tbody></table></div></section>`:''}</div><aside class="detail-aside"><section class="panel"><div class="panel-head"><h2>方案复核</h2>${badge('只读候选')}</div><div class="panel-body">${blocked?`<div class="candidate" style="background:var(--danger-bg);border-color:#edcecb"><h3 class="danger-text">采购流转已阻断</h3><p style="margin-top:8px">${block[0]}</p></div>`:`<div class="candidate"><h3>常规补货候选</h3><div class="big num">${r.qty}<small> 件</small></div><p>${base?`预计 ${state.late?'D8 · 11-18':'D6 · 11-16'} 可售（假设）`:'日期明细待补充'}</p>${badge(base&&state.late?'需重新规划':'待人工复核',base&&state.late?'danger':'success')}</div>`}<div class="key-value"><span>供应商</span><strong>${r.supplier}</strong></div><div class="key-value"><span>采购金额 / 币种</span><strong>— / 尚未提供</strong></div><div class="key-value"><span>发起人</span><strong>林予 · 采购（演示）</strong></div><div class="key-value"><span>审批能力</span><strong>${state.demo?'会话演示':'尚未启用'}</strong></div><div style="margin-top:16px">${blocked||(base&&state.late)||!base?btn(blocked?'补证后重新分析':base&&state.late?'日期已变更，需重新分析':'仅 CB-1001 可演示流转','create-suggestion','primary full','disabled'):state.demo?btn('选择此方案 · 生成建议','create-suggestion','primary full'):btn('预览人工流转','toggle-mode','primary full')}</div><p class="micro-note">${blocked?'阻断不可由人工按钮直接绕过。':'选择才创建建议；确认与提交审批分两步。当前不开放 ERP 写入。'}</p></div></section><section class="panel"><div class="panel-head"><h2>分析来源</h2></div><div class="panel-body"><div class="key-value"><span>分析时点</span><strong>11-11 08:00 UTC+8</strong></div><div class="key-value"><span>快照</span><strong class="mono">snap-demo-1111</strong></div><div class="key-value"><span>历史计划 / 报告</span><strong class="mono">plan-v1 / report-v1</strong></div><div class="key-value"><span>指标 / 候选</span><strong class="mono">metric-v1 / candidate-v1</strong></div>${btn('查看证据与定位 →','evidence','link',`data-id="${r.id}"`)}</div></section></aside></div>`;
  }
  function evidencePanel(r){return `<h2 style="margin-bottom:10px">固定输入与产物引用</h2><p class="micro-note">以下全部为 simulated 定位信息，无真实源系统链接；只有授权可用的证据才能支持结论。</p>${[['D03 快照','snap-demo-1111 / manifest-v1'],['D02 映射','mapping-demo-v1 / unit=件'],['B01 指标','metric-demo-v1 / available'],['B02 候选','candidate-demo-v1 / B01-evaluationRef'],['D04 证据','ev-demo-inventory / row:'+r.sku],['O01 历史报告',SOURCE_REPORT]].map(x=>`<div class="key-value"><span>${x[0]}</span><strong class="mono">${x[1]}</strong></div>`).join('')}<div class="button-row" style="margin-top:16px">${btn('打开库存证据','evidence','',`data-id="${r.id}"`)}${btn('模拟证据无权访问','deny-evidence')}</div>`;}
  function approvalPage(){
    const s=state.suggestion,a=state.approval;
    if(!state.demo)return head('COLLABORATION / APPROVALS','人工审批','后续协作流程预览；当前 S01 只读切片未启用。')+`<section class="panel"><div class="empty"><div style="font-size:30px">☑</div><h2>先复核，再独立审批</h2><p>可预览建议确认、提交、独立审批与版本失效。全部操作仅存在于当前页面会话。</p>${btn('开启审批流程演示','toggle-mode','primary')}<p class="micro-note">批准后仍需另行授权执行；本原型不连接 ERP。</p></div></section>`;
    if(!s)return head('COLLABORATION / APPROVALS','人工审批','会话内流程演示 · 采购建议与审批各自保存状态。')+`<section class="panel"><div class="empty"><div style="font-size:28px">☑</div><h2>暂无人工建议</h2><p>在 CB-1001 详情明确选择候选后，才创建建议草稿。</p><a class="button primary" href="#detail/RP-001">去复核补货方案 →</a></div></section>`;
    const active=currentSuggestion(),pending=currentApproval()&&a.status==='PENDING',approved=currentApproval()&&a.status==='APPROVED',stage=!active?-1:s.status==='DRAFT'?0:s.status==='CONFIRMED'?1:pending?2:approved?3:2;
    return head('COLLABORATION / APPROVALS','人工审批',`SG-DEMO-001 · CB-1001 / 旅行收纳包 · 会话演示`,btn('查看来源报告','source-report'))+
      `<div class="steps">${['生成并确认建议','明确提交审批','独立人员审批','另行授权执行'].map((t,i)=>`<div class="step ${stage===i?'active':stage>i?'done':''}"><b>${i+1}</b>${t}</div>`).join('')}</div>`+
      contextNotice()+(s.status==='SUPERSEDED'?'':s.qty!==20?notice('新数量尚未获得逐日评价','30 件为人工假设，旧 20 件候选的评价与批准不覆盖它。请重新分析；本原型未实现任意参数重算，暂不可确认或提交。','warning'):approved?notice('已批准（演示），未执行','批准仅覆盖建议 v'+a.version+'；不创建采购草稿、不触发任何外部请求。','success'):pending?notice('等待独立审批人决策','切换顶部演示身份为“审批 · 周宁”可预览审批；发起人林予不能审批自己的建议。'):a?.status==='EXPIRED'||a?.status==='REVOKED'?notice(a.status==='EXPIRED'?'批准已过期（演示）':'批准已撤销（演示）','旧批准不可执行；需要重新确认当前版本并提交审批。','warning'):a?.status==='REJECTED'?notice('审批已拒绝（演示）',esc(a.reason),'danger'):notice('建议尚未提交审批','确认只保存 CONFIRMED；明确提交后才进入 PENDING。'))+
      `<div class="detail-grid"><div><section class="panel"><div class="panel-head"><h2>采购草稿建议 <small>版本 v${s.version}</small></h2>${badge(s.status,s.status==='SUBMITTED'?'info':'')}</div><div class="panel-body"><div class="facts"><div class="fact"><span>商品 / 仓库</span><strong>CB-1001 / 美西仓</strong></div><div class="fact"><span>采购数量</span><strong class="num">${s.qty} 件</strong></div><div class="fact"><span>候选预计可售日</span><strong>D6 / 2026-11-16（${active?'假设':'历史建议，已失效'}）</strong></div><div class="fact"><span>来源报告</span><strong>${esc(s.sourceReport)}</strong></div><div class="fact"><span>采购金额 / 币种</span><strong>未提供 / 不计算</strong></div><div class="fact"><span>参数指纹</span><strong class="mono">demo-qty${s.qty}-v${s.version}-scenario${s.scenarioRevision}</strong></div><div class="fact"><span>发起人</span><strong>林予（演示）</strong></div><div class="fact"><span>审批人</span><strong>${a?'周宁（演示）':'尚未提交'}</strong></div></div><p class="micro-note">审批权限、金额阈值和有效期由负责人冻结。本页假定唯一审批人周宁、有效期 24 小时，仅演示版本绑定。</p><div class="button-row" style="margin-top:18px">${active&&s.status==='DRAFT'?btn('确认建议','confirm-suggestion','primary',state.role==='buyer'&&s.qty===20?'':'disabled'):active&&s.status==='CONFIRMED'?btn('提交审批','submit-approval','primary',state.role==='buyer'?'':'disabled'):''}${btn('修改数量 · 新版本','edit-suggestion','',active&&state.role==='buyer'?'':'disabled')}</div>${state.role!=='buyer'?'<p class="micro-note">仅发起人可修改、确认和提交建议。</p>':''}</div></section><section class="panel"><div class="panel-head"><h2>操作记录</h2>${badge('非持久审计')}</div><div class="panel-body">${state.audit.map(x=>`<div class="audit-item">${esc(x.text)}<small>${x.time}</small></div>`).join('')}</div></section></div><aside class="detail-aside"><section class="panel"><div class="panel-head"><h2>审批决策</h2>${badge(a?`${a.status}${currentApproval()?'':' / 历史已失效'}`:'未创建',approved?'success':a?.status==='REJECTED'?'danger':'')}</div><div class="panel-body">${pending?`<p class="small">冻结建议 v${a.version} · ${s.qty} 件</p><p class="micro-note">须核对数量、日期、证据和角色。当前身份：${state.role==='buyer'?'发起人林予':'审批人周宁'}。</p><div class="button-row" style="margin-top:16px">${btn('批准','approve','primary',state.role==='reviewer'?'':'disabled')}${btn('拒绝','reject','danger',state.role==='reviewer'?'':'disabled')}</div>${state.role==='buyer'?'<p class="micro-note">发起人与审批人必须分离，请切换演示身份。</p>':''}`:approved?`<p class="small">批准版本 v${a.version} / 仅覆盖当前指纹。</p><p class="micro-note">演示有效期：24 小时；刷新页面后状态清空。</p><div class="button-row" style="margin-top:16px">${btn('撤销批准','revoke','',state.role==='reviewer'?'':'disabled')}${btn('模拟批准过期','expire','link')}</div>`:`<p class="small muted">${s.status==='DRAFT'?'待发起人确认并提交。':s.status==='CONFIRMED'?'待发起人明确提交。':'当前无有效待审批申请。'}</p>`}</div></section><section class="panel"><div class="panel-head"><h2>外部执行</h2>${badge('未启用')}</div><div class="panel-body"><p class="small">创建 ERP 采购草稿</p><p class="micro-note">批准不等于下单、发货或到货。执行须独立授权，并复核批准、源条件与证据。</p>${btn('当前只读 · 不开放执行','execute','full','disabled')}<div style="margin-top:12px">${btn('预览回执未知处理','unknown','link')}</div></div></section></aside></div>`;
  }
  function render(){const r=route(),known=['workbench','suggestions','detail','approvals'].includes(r.page);if(!known){go('workbench');return;}$('#main').innerHTML=r.page==='suggestions'?suggestions():r.page==='detail'?detail():r.page==='approvals'?approvalPage():workbench();$('#crumb').textContent={workbench:'工作台',suggestions:'补货建议',detail:'建议详情',approvals:'人工审批'}[r.page];document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(r.page==='detail'?'suggestions':r.page);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('.prototype-bar').classList.toggle('demo',state.demo);$('#mode-text').textContent=state.demo?'审批流程演示 · 无外部写入 / 刷新清空':'S01 只读 · 全部为模拟数据';$('#mode-button').textContent=state.demo?'返回只读预览':'预览审批流程 ↗';$('#role').value=state.role;$('#avatar').textContent=state.role==='buyer'?'林':'周';}
  function about(){modal('原型范围与待确认',`<p>本原型用于审查功能与操作流程；根目录 DESIGN.md 规定视觉表达。未经负责人确认，不进入正式前端开发。</p><ul class="scope-list"><li><b>已实现交互：</b>导航、搜索筛选、排序、详情、固定逐日样例、证据侧读、导出、模拟分析/取消、确认/提交/独立审批/拒绝/版本失效。</li><li><b>占位演示：</b>店铺/SKU/仓/供应商、数量日期、报告、角色、质量阈值、预算、审批期限与日志，均为模拟。</li><li><b>尚未实现：</b>ERP/OMS/WMS/CRM、B01/B02/O01、模型、服务端权限、持久化、真实审批、执行、下载鉴权、异步恢复。</li><li><b>需确认：</b>输入口径/时效与质量矩阵；试点范围；候选参数与交期；审批角色、金额与期限；只读首期及后续协作范围。</li></ul><p><a href="../../docs/ui/PRODUCT_SPEC.md" target="_blank" rel="noopener">产品原型规格</a> · <a href="../../docs/ui/ALIGNMENT.md" target="_blank" rel="noopener">需求一致性与缺口</a> · <a href="../../DESIGN.md" target="_blank" rel="noopener">视觉规范</a></p>`,btn('已了解','close','primary'));}
  function toggleMode(){if(state.demo){state.demo=false;render();toast('已返回 S01 只读预览；演示建议仍保留于本会话。');return;}modal('进入人工协作流程演示',`<p>当前 S01 只读分析到报告结束。以下流程预览后续 C01 / C02 的人工操作，并未启用真实审批。</p>${notice('所有更改仅保留在当前页面内存','不连接任何企业系统。刷新页面即恢复初始状态；审批后不会执行采购。','warning')}`,btn('继续只读','close')+btn('开启演示','enable-demo','primary'));}
  function analysisForm(){modal('新建补货分析',`<form id="analysis-form"><div class="form-grid"><label class="field">店铺<select id="analysis-store"><option>Amazon 美国站</option></select></label><label class="field">仓库<select id="analysis-warehouse"><option>美西仓</option></select></label><label class="field">SKU（仅开放固定样例）<input id="analysis-sku" value="CB-1001" required pattern="CB-1001"><span class="muted small">样例目录：CB-1001</span></label><label class="field">分析时点<input value="2026-11-11 08:00 UTC+08:00" readonly aria-label="分析时点"></label><label class="field">需求窗口<input value="7 天 / 日新增需求 10 件" readonly></label><label class="field">目标缓冲<input value="2 天" readonly></label></div><label class="field" style="margin-top:16px">模拟运行情景<select id="analysis-outcome"><option value="normal">规则样例成功</option><option value="model">模型解释不可用 · 保留规则报告</option><option value="b02">候选能力不可用 · 仅基线</option><option value="blocked">必需质量缺失 · 阻断</option><option value="yield">暂停等待 · 不发布报告</option></select></label><p class="micro-note">固定时点、输入与限额仅为演示，不推断真实企业预算。无需模型；不发送 API 请求。</p><div id="analysis-error" class="field-error" role="alert"></div></form>`,btn('取消','close')+btn('开始模拟分析','run-analysis','primary'));}
  function runAnalysis(){if(!$('#analysis-form').reportValidity())return;const outcome=$('#analysis-outcome').value;close();clearTimeout(jobTimer);const sequence=++state.jobSequence;state.job={id:`task-demo-session-${sequence}`,report:null,status:'运行中',message:'已受理模拟请求 · 读取固定样例；未发布报告。'};go('workbench');render();jobTimer=setTimeout(()=>{if(state.job?.status!=='运行中')return;const info={normal:['已发布','RULES_ONLY · 固定规则报告可复核，无模型调用。本次仅复用原计划样例，不采用详情延期预览。'],model:['已发布','RULES_ONLY · 解释服务不可用；规则报告保留，质量门槛仍有效。本次仅复用原计划样例，不采用详情延期预览。'],b02:['仅基线','B02 不可用 · 仅对照历史基线，不生成候选；本次未发布报告。'],blocked:['已阻断','必需质量信号缺失 · 不输出可执行补货结论；本次未发布报告。'],yield:['暂停等待','YIELD · 未发布报告，未重置原任务期限或额度。']}[outcome];state.job={...state.job,status:info[0],message:info[1],report:['normal','model'].includes(outcome)?`report-demo-session-${sequence}`:null};render();toast('模拟分析状态已更新。');},1800);}
  function createSuggestion(){if(!state.demo||state.role!=='buyer'||state.late||route().id!=='RP-001'){toast('当前范围、角色或情景不允许生成建议。');return;}if(state.suggestion&&state.suggestion.status!=='SUPERSEDED'){go('approvals');toast('已打开本会话中原有建议，未重复创建。');return;}modal('选择候选并生成建议',`<p>CB-1001 / 美西仓 · 常规补货 20 件 · 假设 D6 可售。</p><p>此操作只生成建议草稿。后续还需确认、明确提交和独立审批。</p>`,btn('取消','close')+btn('生成建议草稿','save-suggestion','primary'));}
  function saveSuggestion(){if(!state.demo||state.role!=='buyer'||state.late||(state.suggestion&&state.suggestion.status!=='SUPERSEDED'))return;const version=(state.suggestion?.version||0)+1;state.suggestion={qty:20,version,status:'DRAFT',scenarioRevision:state.scenarioRevision,sourceReport:SOURCE_REPORT};state.approval=null;log(`林予选择历史原计划候选20件，创建建议 v${version} / DRAFT / 情景修订${state.scenarioRevision}；旧审批不继承。`);close();go('approvals');toast('建议草稿已生成（演示），尚未确认或提交。');}
  function confirmSuggestion(){if(!state.demo||!currentSuggestion()||state.role!=='buyer'||state.suggestion?.status!=='DRAFT')return;if(state.suggestion.qty!==20){toast('新数量尚未评价，请先重新分析。');return;}modal('确认当前建议',`<p>确认建议 v${state.suggestion.version}，数量 ${state.suggestion.qty} 件，预计 D6 可售（假设）。</p><label class="check-line"><input type="checkbox" id="confirm-check">我已复核范围、数量、假设日期和来源证据。</label><div id="confirm-error" class="field-error" role="alert"></div>`,btn('返回复核','close')+btn('保存确认','save-confirm','primary'));}
  function saveConfirm(){if(!state.demo||!currentSuggestion()||state.role!=='buyer'||state.suggestion?.status!=='DRAFT'||state.suggestion.qty!==20)return;if(!$('#confirm-check').checked){$('#confirm-error').textContent='请先完成复核确认。';return;}state.suggestion.status='CONFIRMED';log(`林予确认建议 v${state.suggestion.version} / CONFIRMED；未创建审批。`);close();render();toast('已确认，仍需明确提交审批。');}
  function submitApproval(){if(!state.demo||!currentSuggestion()||state.role!=='buyer'||state.suggestion?.status!=='CONFIRMED')return;modal('提交独立审批',`<p>冻结建议 v${state.suggestion.version} 与参数指纹，交由周宁（演示审批人）审核。</p><p>提交后产生 PENDING；不会创建外部采购草稿。</p>`,btn('取消','close')+btn('明确提交审批','save-submit','primary'));}
  function saveSubmit(){if(!state.demo||!currentSuggestion()||state.role!=='buyer'||state.suggestion?.status!=='CONFIRMED')return;state.suggestion.status='SUBMITTED';state.approval={status:'PENDING',version:state.suggestion.version,scenarioRevision:state.suggestion.scenarioRevision,sourceReport:state.suggestion.sourceReport};log(`林予提交建议 v${state.suggestion.version}，审批 PENDING。`);close();render();toast('已提交审批（演示）；同一版本不重复创建申请。');}
  function decisionForm(kind){if(!state.demo||!currentSuggestion()||state.role!=='reviewer'||!currentApproval()||state.approval?.status!=='PENDING')return;const approve=kind==='approve';modal(approve?'批准当前冻结版本':'拒绝当前申请',`<p>建议 v${state.approval.version} · ${state.suggestion.qty} 件。${approve?'批准不触发执行。':'请说明需补充或调整的事项。'}</p><label class="field">${approve?'审批意见（可选）':'拒绝原因（必填）'}<textarea id="decision-reason" maxlength="500" placeholder="填写具体依据"></textarea></label><div id="decision-error" class="field-error" role="alert"></div>`,btn('取消','close')+btn(approve?'确认批准':'确认拒绝',approve?'save-approve':'save-reject',approve?'primary':'danger'));}
  function saveDecision(kind){if(!state.demo||!currentSuggestion()||state.role!=='reviewer'||!currentApproval()||state.approval?.status!=='PENDING')return;const reason=$('#decision-reason').value.trim();if(kind==='REJECTED'&&!reason){$('#decision-error').textContent='请输入拒绝原因。';$('#decision-reason').focus();return;}state.approval={...state.approval,status:kind,reason};if(kind==='REJECTED')state.suggestion.status='DRAFT';log(`周宁${kind==='APPROVED'?'批准':'拒绝'}建议 v${state.approval.version}${reason?'：'+reason:''}。未创建执行。`);close();render();toast(kind==='APPROVED'?'已批准（演示），外部执行仍未启用。':'已拒绝（演示）。');}
  function editSuggestion(){if(!state.demo||!currentSuggestion()||state.role!=='buyer'||!state.suggestion)return;modal('修改数量并生成新版本',`${notice('当前确认与批准将不再覆盖新版本','新版本回到 DRAFT，需要重新确认与提交。旧报告指标不会随手工修改而重新计算。','warning')}<label class="field">数量（件）<select id="edit-qty"><option value="20" ${state.suggestion.qty===20?'selected':''}>20</option><option value="30" ${state.suggestion.qty===30?'selected':''}>30</option></select></label><p class="micro-note">仅开放演示值 20 / 30，均符合 MOQ10 / 倍数10。30 件是人工假设，尚无 B01 逐日评价，不展示计算收益。</p>`,btn('取消','close')+btn('保存新版本','save-edit','primary'));}
  function saveEdit(){if(!state.demo||!currentSuggestion()||state.role!=='buyer'||!state.suggestion)return;const qty=Number($('#edit-qty').value);if(qty===state.suggestion.qty){toast('数量未变化，保留当前版本。');return;}const old=state.suggestion.version;log(`林予修改 ${state.suggestion.qty} → ${qty} 件；旧 v${old} 确认/批准不覆盖新版本。`);state.suggestion={...state.suggestion,qty,version:old+1,status:'DRAFT'};state.approval=null;close();render();toast('已生成新版本；原批准不可复用，待重新确认。');}
  function evidence(id){const r=rowById(id);modal('库存证据 · simulated',`<p><b>${r.sku} / ${r.warehouse}</b></p><div class="key-value"><span>来源引用</span><strong class="mono">WMS-demo / inventory-row-${r.sku}</strong></div><div class="key-value"><span>快照 / 映射</span><strong class="mono">snap-demo-1111 / mapping-v1</strong></div><div class="key-value"><span>sourceUpdatedAt</span><strong>${r.status==='stale'?'2026-11-09':'2026-11-11'} 07:50 UTC+8</strong></div><div class="key-value"><span>coverageThrough</span><strong>${r.status==='stale'?'2026-11-09':'2026-11-11'} 08:00 UTC+8</strong></div><div class="key-value"><span>observedAt</span><strong>2026-11-11 08:01 UTC+8</strong></div>${r.id==='RP-001'?'<p style="margin-top:14px">现货 100 / 预留 30 / 冻结 10 / 不可售 5（件）。互斥分桶；已预留需求不再作为新增需求重复扣减。</p>':''}<p class="micro-note">这是本地样例定位卡。真实证据解析、源链接、字段权限与下载重新鉴权尚未实现。</p>`,btn('模拟无权访问','deny-evidence')+btn('关闭','close','primary'));}
  function unknown(){modal('执行回执未知 · 处理预览',`${notice('UNKNOWN 不代表失败，也不代表未创建','可能已创建 ERP 草稿但回执丢失。必须使用原 executionKey 核对，禁止换 key 重发。','warning')}<div class="key-value"><span>执行状态</span><strong>UNKNOWN（固定演示）</strong></div><div class="key-value"><span>原 executionKey</span><strong class="mono">exec-demo-original-001</strong></div><p class="micro-note">此处不创建执行、不查询真实回执。仅演示核对结果仍未知时转人工的处理路径。</p><div id="receipt-result"></div>`,btn('关闭','close')+btn('按原键模拟核对','query-receipt','primary'));}
  function exportDemo(){const rows=filtered();const values=[['simulated','SKU','店铺','仓库','可售件数','候选件数','状态'],...rows.map(r=>['true',r.sku,r.store,r.warehouse,r.available??'UNKNOWN',r.qty??'BLOCKED',D.states[r.status][0]])];const csv='\ufeff'+values.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='SIMULATED-补货候选.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前筛选的模拟结果；不是采购单。');}
  function clearFilters(){Object.assign(state,{tab:'all',search:'',warehouse:'all',store:'all',sort:'risk'});render();}
  const actions={
    about,close,'toggle-mode':toggleMode,'enable-demo':()=>{state.demo=true;close();render();toast('已开启审批流程演示。');},
    reset:()=>{modal('重置全部演示状态',`<p>清空当前页面内的建议、审批、记录与模拟任务，恢复 S01 只读预览。</p>`,btn('保留','close')+btn('重置','confirm-reset','primary'));},
    'confirm-reset':()=>{clearTimeout(jobTimer);state=initial();close();go('workbench');render();toast('演示状态已重置。');},
    'filter-ready':()=>{clearFilters();state.tab='ready';go('suggestions');},'filter-blocked':()=>{clearFilters();state.tab='blocked';go('suggestions');},'open-approvals':()=>go('approvals'),
    tab:el=>{state.tab=el.dataset.value;render();},'detail-tab':el=>{state.detailTab=el.dataset.value;render();},'clear-filters':clearFilters,
    'new-analysis':analysisForm,'run-analysis':runAnalysis,'cancel-job':()=>{if(state.job?.status!=='运行中')return;clearTimeout(jobTimer);state.job.report=null;state.job.status='已取消';state.job.message='模拟任务已在安全边界取消，未发布本次报告。';render();},
    'create-suggestion':createSuggestion,'save-suggestion':saveSuggestion,'confirm-suggestion':confirmSuggestion,'save-confirm':saveConfirm,'submit-approval':submitApproval,'save-submit':saveSubmit,
    approve:()=>decisionForm('approve'),reject:()=>decisionForm('reject'),'save-approve':()=>saveDecision('APPROVED'),'save-reject':()=>saveDecision('REJECTED'),
    'edit-suggestion':editSuggestion,'save-edit':saveEdit,'source-report':()=>{state.detailTab='overview';go('detail/RP-001');},
    revoke:()=>{if(!state.demo||!currentApproval()||state.role!=='reviewer'||state.approval?.status!=='APPROVED')return;modal('撤销批准',`<p>撤销后旧批准不可执行；此处没有在途执行请求。</p>`,btn('取消','close')+btn('确认撤销','save-revoke','danger'));},
    'save-revoke':()=>{if(!state.demo||!currentApproval()||state.role!=='reviewer'||state.approval?.status!=='APPROVED')return;state.approval.status='REVOKED';state.suggestion.status='DRAFT';log('周宁撤销批准；需重新确认和提交。');close();render();},
    expire:()=>{if(!state.demo||!currentApproval()||state.approval?.status!=='APPROVED')return;state.approval.status='EXPIRED';state.suggestion.status='DRAFT';log('模拟批准有效期届满，旧批准不可执行。');render();},
    evidence:el=>evidence(el.dataset.id||route().id),'deny-evidence':()=>modal('证据不可访问',`${notice('无权访问或证据不可用','无法核实该项依据。请联系数据负责人；本次访问不返回敏感源内容。','danger')}<p class="micro-note">模拟 403/404 安全反馈；真实后端权限尚未实现。</p>`,btn('关闭','close','primary')),
    unknown,'query-receipt':el=>{el.disabled=true;$('#receipt-result').innerHTML=notice('原键核对后仍未决','保留 UNKNOWN 与原 executionKey，转交有权限人员核对。不得新建发送请求。','warning');},export:exportDemo
  };
  document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled){actions[el.dataset.action]?.(el);}});
  document.addEventListener('input',event=>{if(event.target.id==='search'){state.search=event.target.value;$('#result-table').innerHTML=tableBody();}});
  document.addEventListener('change',event=>{const {id,value}=event.target;if(['warehouse','store','sort'].includes(id)){state[id]=value;$('#result-table').innerHTML=tableBody();}else if(id==='role'){state.role=value;if($('#modal').open)close();render();toast('已切换演示身份；真实服务端鉴权尚未实现。');}else if(id==='scenario'){changeScenario(value==='late');}});
  window.addEventListener('hashchange',()=>{render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);});
  $('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)close();}});
  $('#modal').addEventListener('cancel',()=>returnFocus?.focus?.());
  render();
})();
